    [Xunit.Fact]
    public static void TestOcrTextIsTaggedAsOcrOnThePagesThatWereRead() {
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells mask = emon.Port.NewCells();
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        Model.PageNew(pages, 1, 61200, 79200, 0, Model.PkVector());
        Model.PageNew(pages, 2, 61200, 79200, 0, Model.PkVector());
        int p1 = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        int t1 = Model.NodeNew(nodes, Model.NkText(), p1);
        int p2 = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        int t2 = Model.NodeNew(nodes, Model.NkText(), p2);
        Model.NodeAddRegion(nodes, regions, p1, 1, 0, 0, 100, 100);
        Model.NodeAddRegion(nodes, regions, p2, 2, 0, 0, 100, 100);
        Model.NodeAddSrc(nodes, p1, Model.SrText());
        Model.NodeAddSrc(nodes, p1, Model.SrInfer());
        Model.NodeAddSrc(nodes, t1, Model.SrText());
        Model.NodeSetConf(nodes, t1, 1000);
        Model.NodeAddSrc(nodes, p2, Model.SrText());
        Model.NodeAddSrc(nodes, t2, Model.SrText());
        Model.NodeSetConf(nodes, t2, 1000);
        emon.Port.CellsPush(mask, 2);
        emon.Port.CellsPush(mask, 0);
        emon.Testport.AssertEq(Scan.ScTag(nodes, attrs, text, regions, pages, mask, 2), 1, "something was tagged");
        emon.Testport.AssertEq(Model.NodeSrc(nodes, p1), Model.SrOcr() + Model.SrInfer(), "page 1's paragraph: `ocr` for `text`, `infer` kept");
        emon.Testport.AssertEq(Model.NodeSrc(nodes, t1), Model.SrOcr(), "its text");
        emon.Testport.AssertEq(Model.NodeConf(nodes, t1), 500, "an engine's word is not a glyph's own text: uncalibrated 500");
        emon.Testport.AssertEq(Model.NodeFlags(nodes, p1), Model.FlOcrOnly(), "the block says it is OCR only");
        emon.Testport.AssertEq(Model.NodeFlags(nodes, t1), 0, "an inline is not flagged");
        emon.Testport.AssertEq(Model.NodeSrc(nodes, p2), Model.SrText(), "page 2 was not OCR'd: untouched");
        emon.Testport.AssertEq(Model.NodeConf(nodes, t2), 1000, "and so is its confidence");
        emon.Testport.AssertEq(Model.PageKind(pages, 0), Model.PkScanned(), "a PDF page that was read is `scanned`");
        emon.Testport.AssertEq(Model.PageKind(pages, 1), Model.PkVector(), "the other is not");
        int a = Model.NodeAttr(nodes, attrs, 0, Model.FkOcr());
        emon.Testport.AssertThat(a >= 0, "settings.ocr is written");
        emon.Testport.AssertEq(Model.AttrLen(attrs, a), 6, "`always`");
    }
